<?php elseif($screen==='/membership/reports'): ?><section class="card section"><h2>گزارش تجمیعی</h2><?php foreach($stats as $key=>$value): ?><p><?= $this->h(['users'=>'حساب‌های فعال','verified_organizations'=>'مجموعه‌های احرازشده','networks'=>'شبکه‌های فعال'][$key]) ?>: <?= $this->number($value) ?></p><?php endforeach; ?><p class="small muted">مهمان حساب کاربری ندارد؛ تعداد بازدیدکنندگان ناشناس با تعداد حساب‌ها یکسان فرض نمی‌شود.</p><?php foreach($states as $stat): ?><p><?= $this->h($this->status($stat['state'])) ?>: <?= $this->number($stat['total']) ?></p><?php endforeach; ?><h3>اعتبارها</h3><?php foreach($creditStats as $stat): ?><p><?= $this->h($label($stat['state'])) ?>: <?= $this->number($stat['total']) ?></p><?php endforeach; ?><h3>موضوع‌ها و مسئله‌های پرتکرار در درخواست‌ها</h3><?php foreach($frequentIssues as $item): ?><p><?= $this->h($item['title']) ?>: <?= $this->number($item['total']) ?></p><?php endforeach; ?></section><?php endif; ?>
<?php if(!empty($history)): ?><section class="card section"><h2>تاریخچهٔ تصمیم‌های عضویت و اختیارات</h2><?php foreach($history as $event): ?><details class="membership-record"><summary><?= $this->h($event['action'].' — '.\Morshed\Product\Consultations::sessionLabel((int)$event['created_at'])) ?></summary><p>حساب ثبت‌کننده: <?= $this->h($event['actor_id']) ?></p><p>شناسهٔ مرتبط: <?= $this->h($event['subject_id']) ?></p><pre><?= $this->h($event['before_json']) ?></pre><pre><?= $this->h($event['after_json']) ?></pre></details><?php endforeach; ?></section><?php endif; ?>
</div>